      expect(undoCommand).toHaveBeenCalledOnce();
      expect(history.getValue()).toBe(emptyMarkdown);
      expect(surface.querySelector('pre > code')?.textContent).toBe('\n');

      const undoBody = new KeyboardEvent('keydown', {
        bubbles: true,
        cancelable: true,
        ctrlKey: true,
        key: 'z'
      });
