      expect(requestPreview).not.toHaveBeenCalled();
      expect(onFailure).not.toHaveBeenCalled();

      const undo = new KeyboardEvent('keydown', {
        bubbles: true,
        cancelable: true,
        ctrlKey: true,
        key: 'z'
      });
