      expect(heldLease?.resolve()).toBeNull();
      fixture.accept({
        editMap: fullOwnerEditMap('full-owner-paste-accepted', [
          { endLine: 1, id: 'b0', startLine: 0 }
        ]),
        html: fullOwnerParagraphBlock(source, 'b0'),
        markdown: source
      });
      act(() => {
        vi.advanceTimersByTime(0);
      });
